        jobs.append((zp, os.path.join(outd, sym, day + ".csv")))
    print("файлов", len(jobs), flush=True)
    with Pool(nproc) as p:
        for i, (o, n, s) in enumerate(p.imap_unordered(one, jobs), 1):
            print(i, o, n, s, flush=True)
    print("готово", flush=True)

